  isPropertyOf,
  isRegexp,
  isSet,
  isString,
  isSymbol,
  isUndefined,
  isUrl,
  isWeakMap,
  isWeakSet,
} from './standalone';
import type { TypeName } from './types';

function is(value: unknown): TypeName {
  if (value === null) {
    return 'null';
  }

  switch (typeof value) {
    case 'bigint':
      return 'bigint';
    case 'boolean':
      return 'boolean';
    case 'number':
      return 'number';
    case 'string':
      return 'string';
    case 'symbol':
      return 'symbol';
    case 'undefined':
      return 'undefined';
    default:
  }

  if (isArray(value)) {
    return 'Array';
  }

  if (isPlainFunction(value)) {
    return 'Function';
  }

  const tagType = getObjectType(value);

  /* v8 ignore next -- @preserve */
  if (tagType) {
    return tagType;
  }

  /* v8 ignore next -- @preserve */
  return 'Object';
}

